# Generated by clients/macos/ci/release.sh in the switchback repository.
class Switchbak < Formula
  desc "Carry AI coding agent sessions to switchback"
  homepage "https://switchbak.dev"
  url "https://github.com/switchbackai/homebrew-tap/releases/download/v0.1.1/switchbak-0.1.1.zip"
  sha256 "41470fc514dc2478a4f145aede494f66e3aa4c0a9d3555ef8e17187fc2207d5e"

  depends_on arch: :arm64
  depends_on :macos

  # No `service do`: `switchbak setup` writes the launch agents, with the
  # host and the endpoint that `brew services` does not know.
  def install
    bin.install "bin/switchbak"
    share.install "share/switchbak"
  end

  def caveats
    <<~EOS
      To watch the sessions on this Mac and load the launch agents:
        switchbak setup
      Before `brew uninstall switchbak`, run:
        switchbak teardown
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/switchbak version")
  end
end
